style.css:
@-moz-document domain("google.com") {
/* 1. Hide the original Google logo image */
    img[alt="Google"], .lnXdpd, .k1z7rd, .jfN4p {
        opacity: 0 !important;
    }

    /* 2. Create the container for the new logo */
    .k1z7rd, .LLD4me, .logo {
        position: relative;
        display: flex;
        justify-content: center;
        align-items: center;
    }

    /* 3. Style the word "COSMOS" with Google's color palette */
    .k1z7rd::before, .LLD4me::before {
        content: "COSMOS";
        position: absolute;
        
        /* Font styling to match Google's clean look */
        font-family: 'Product Sans', Arial, sans-serif;
        font-size: 80px; 
        font-weight: 700;
        letter-spacing: -2px;
        
        /* Google's specific color sequence (C-O-S-M-O-S) */
        background: linear-gradient(to right, 
            #4285F4 0% 16.6%,    /* Blue   (C) */
            #EA4335 16.6% 33.3%, /* Red    (O) */
            #FBBC05 33.3% 50%,   /* Yellow (S) */
            #4285F4 50% 66.6%,   /* Blue   (M) */
            #34A853 66.6% 83.3%, /* Green  (O) */
            #EA4335 83.3% 100%   /* Red    (S) */
        );
        
        /* Apply colors to the text */
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        
        pointer-events: none;
        z-index: 999;
    }
}
